// Paginate returns a page of time_entries with total count for offset-based pagination.
// A nil filter paginates all time_entries.
func (c *timeEntryClient) Paginate(ctx context.Context, input PaginateInput[TimeEntryFilter], opts ...func(*CallOptions[TimeEntryFieldOptions])) (*PaginateResult[TimeEntry], error) {
	options := resolveCallOptions(opts)

	if options.LockMode != sql.LockNone {
		if !database.InTransaction(ctx) {
			return nil, fmt.Errorf("paginate time_entries: LockMode requires an active transaction")
		}
		options.SkipCache = true
	}
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpPaginate, Table: TableTimeEntries, Schema: "public",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[TimeEntryFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Total count (delegates to Count — both are always generated)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, err
		}

		// Page data via GetMany (handles FieldOptions and relationships)
		timeEntries, err := c.GetMany(ctx, &GetTimeEntriesInput{
			Filter: input.Filter,
			Sorts:  input.Sort,
			Limit:  &input.Limit,
			Offset: &input.Offset,
		}, internalOpts)
		if err != nil {
			return nil, err
		}

		return &PaginateResult[TimeEntry]{
			Items:      timeEntries,
			TotalCount: totalCount,
			Offset:     input.Offset,
			Limit:      input.Limit,
			HasMore:    input.Limit > 0 && int64(input.Offset+input.Limit) < totalCount,
		}, nil
	})
	if err != nil {
		return nil, fmt.Errorf("paginate time_entries: %w", err)
	}
	if result == nil {
		return nil, nil
	}
	return result.(*PaginateResult[TimeEntry]), nil
}

// Connection returns a Relay-style cursor-paginated connection of time_entries.
// Sort order is determined by cursor_keys — custom sorts are not supported.
// Use Paginate for custom sort orders.
func (c *timeEntryClient) Connection(ctx context.Context, input ConnectionInput[TimeEntryFilter], opts ...func(*CallOptions[TimeEntryFieldOptions])) (*Connection[TimeEntry], error) {
	options := resolveCallOptions(opts)

	if options.LockMode != sql.LockNone {
		if !database.InTransaction(ctx) {
			return nil, fmt.Errorf("connection time_entries: LockMode requires an active transaction")
		}
		options.SkipCache = true
	}
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpConnection, Table: TableTimeEntries, Schema: "public",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[TimeEntryFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Validate: first and last are mutually exclusive
		if input.First != nil && input.Last != nil {
			return nil, ErrInvalidCursor
		}

		// Total count (separate COUNT query — no cursor conditions)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, err
		}

		// Decode cursors and build keyset conditions
		var keysetConds []sql.Condition
		if input.After != nil {
			cursor, err := decodeTimeEntryCursor(*input.After, c.cursorKeys)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, ">"))
		}
		if input.Before != nil {
			cursor, err := decodeTimeEntryCursor(*input.Before, c.cursorKeys)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, "<"))
		}

		// Direction and limit
		limit := c.pageSize
		ascending := true
		if input.First != nil {
			limit = *input.First
		} else if input.Last != nil {
			limit = *input.Last
			ascending = false
		}

		// Fetch limit+1 rows via GetMany (handles FieldOptions, O2O joins, relationships, soft delete)
		connLimit := limit + 1
		timeEntries, err := c.GetMany(ctx, &GetTimeEntriesInput{
			Filter:     input.Filter,
			Sorts:      cursorSorts(c.cursorKeys, ascending),
			Limit:      &connLimit,
			conditions: keysetConds,
			// Each edge's cursor is encoded from the row it wraps, so the cursor
			// keys have to survive a narrowed FieldOptions — otherwise the
			// encoder reads fields the SELECT never filled and every cursor
			// carries zero values.
			requiredColumns: c.cursorKeys,
		}, internalOpts)
		if err != nil {
			return nil, err
		}

		// Trim extra row and determine page boundaries
		hasMore := len(timeEntries) > limit
		if hasMore {
			timeEntries = timeEntries[:limit]
		}

		// Backward pagination: reverse for ascending cursor order
		if !ascending {
			slices.Reverse(timeEntries)
		}

		// Build edges with encoded cursors
		edges := make([]Edge[TimeEntry], len(timeEntries))
		for i, row := range timeEntries {
			cursor, err := encodeTimeEntryCursor(c.cursorKeys, row)
			if err != nil {
				return nil, err
			}
			edges[i] = Edge[TimeEntry]{
				Node:   row,
				Cursor: cursor,
			}
		}

		pageInfo := PageInfo{
			HasNextPage:     (ascending && hasMore) || (!ascending && input.Before != nil),
			HasPreviousPage: (!ascending && hasMore) || (ascending && input.After != nil),
		}
		if len(edges) > 0 {
			pageInfo.StartCursor = &edges[0].Cursor
			pageInfo.EndCursor = &edges[len(edges)-1].Cursor
		}

		return &Connection[TimeEntry]{Edges: edges, PageInfo: pageInfo, TotalCount: totalCount}, nil
	})
	if err != nil {
		return nil, fmt.Errorf("connection time_entries: %w", err)
	}
	if result == nil {
		return nil, nil
	}
	return result.(*Connection[TimeEntry]), nil
}

// encodeTimeEntryCursor encodes cursor key values as a base64 JSON string.
func encodeTimeEntryCursor(keys []string, t *TimeEntry) (string, error) {
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		switch key {
		case "id":
			out["id"] = t.ID
		case "workspace_id":
			out["workspace_id"] = t.WorkspaceID
		case "task_id":
			out["task_id"] = t.TaskID
		case "user_id":
			out["user_id"] = t.UserID
		case "hours":
			out["hours"] = t.Hours
		case "billable":
			out["billable"] = t.Billable
		case "notes":
			out["notes"] = t.Notes
		case "spent_on":
			out["spent_on"] = t.SpentOn
		case "created_at":
			out["created_at"] = t.CreatedAt
		}
	}
	data, err := json.Marshal(out)
	if err != nil {
		return "", fmt.Errorf("encode time_entry cursor: %w", err)
	}
	return base64.StdEncoding.EncodeToString(data), nil
}

// decodeTimeEntryCursor decodes a cursor string into its key values,
// each unmarshaled into the key column's Go type.
func decodeTimeEntryCursor(encoded string, keys []string) (map[string]any, error) {
	raw, err := decodeCursor(encoded, keys)
	if err != nil {
		return nil, err
	}
	var row TimeEntry
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		switch key {
		case "id":
			err = json.Unmarshal(raw[key], &row.ID)
			out[key] = row.ID
		}
		if err != nil {
			return nil, err
		}
		if cursorValueIsNull(out[key]) {
			return nil, ErrInvalidCursor
		}
	}
	return out, nil
}

